export default App;

import { Transaction, BankAccount } from '../types';
import { formatCurrency, formatDate } from './formatters';

declare global {
    interface Window {
        jspdf: any;
    }
}

interface PdfOptions {
    account: BankAccount;
    period: { start: string; end: string };
    transactionsInPeriod: Transaction[];
    allTransactions: Transaction[];
    transactionType: 'checking_account' | 'credit_card';
    title: string;
}

const calculateBalanceUpToDate = (accountId: string, upToDate: Date, allTransactions: Transaction[]): number => {
    const previousTransactions = allTransactions.filter(t => {
        const tDate = new Date(t.date);
        return t.accountId === accountId && t.type === 'checking_account' && tDate < upToDate;
    });

    const balance = previousTransactions.reduce((acc, curr) => {
        if (curr.nature === 'RECEITA') {
            return acc + curr.value;
        }
        return acc - curr.value;
    }, 0);

    return balance;
};


export const generateTransactionsPDF = (options: PdfOptions) => {
    const { account, period, transactionsInPeriod, allTransactions, transactionType, title } = options;
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation: 'portrait' });

    const isCheckingAccount = transactionType === 'checking_account';

    // Header
    doc.setFontSize(18);
    doc.text(isCheckingAccount ? 'Extrato de Conta Corrente' : title, 14, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Conta: ${account.name}`, 14, 29);
    doc.text(`Período: ${formatDate(period.start)} a ${formatDate(period.end)}`, 14, 36);

    let startY = 50;
    let previousBalance = 0;

    if (isCheckingAccount) {
        const startOfDay = new Date(period.start);
        startOfDay.setUTCHours(0, 0, 0, 0);
        previousBalance = calculateBalanceUpToDate(account.id, startOfDay, allTransactions);

        const yesterday = new Date(period.start);
        yesterday.setUTCDate(yesterday.getUTCDate() - 1);
        doc.setFontSize(10);
        doc.setFont(undefined, 'bold');
        doc.text(`Saldo em ${formatDate(yesterday.toISOString())}: ${formatCurrency(previousBalance)}`, 14, 46);
        doc.setFont(undefined, 'normal');
    } else {
        startY = 42;
    }

    const tableColumn = isCheckingAccount
        ? ["Data", "Descrição", "Entrada (+)", "Saída (-)", "Saldo"]
        : ["Data", "Descrição", "Entrada (+)", "Saída (-)"];

    const tableRows: (string | number)[][] = [];
    let runningBalance = previousBalance;
    let totalEntradas = 0;
    let totalSaidas = 0;

    const sortedTransactions = [...transactionsInPeriod].sort((a,b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    sortedTransactions.forEach(t => {
        const entrada = t.nature === 'RECEITA' ? t.value : 0;
        const saida = t.nature === 'DESPESA' ? t.value : 0;

        runningBalance += entrada - saida;
        totalEntradas += entrada;
        totalSaidas += saida;

        const transactionData: (string|number)[] = [
            formatDate(t.date),
            t.description,
            entrada > 0 ? formatCurrency(entrada) : '-',
            saida > 0 ? formatCurrency(saida) : '-',
        ];
        if (isCheckingAccount) {
            transactionData.push(formatCurrency(runningBalance));
        }
        tableRows.push(transactionData);
    });

    doc.autoTable({
        head: [tableColumn],
        body: tableRows,
        startY: startY,
        theme: 'grid',
        headStyles: { fillColor: [37, 99, 235] }, // Blue
        didDrawPage: (data: any) => {
            const pageCount = doc.internal.getNumberOfPages();
            doc.setFontSize(10);
            doc.text(`Página ${data.pageNumber} de ${pageCount}`, data.settings.margin.left, doc.internal.pageSize.height - 10);
        }
    });

    const finalY = doc.lastAutoTable.finalY + 10;
    doc.setFontSize(12);
    doc.text('Resumo do Período', 14, finalY);
    doc.setFontSize(10);

    let summaryY = finalY + 7;
    if (isCheckingAccount) {
        doc.text(`Saldo Anterior: ${formatCurrency(previousBalance)}`, 14, summaryY);
        summaryY += 7;
    }

    doc.text(`Total de Entradas: ${formatCurrency(totalEntradas)}`, 14, summaryY);
    summaryY += 7;
    doc.text(`Total de Saídas: ${formatCurrency(totalSaidas)}`, 14, summaryY);
    summaryY += 7;

    doc.setFontSize(11);
    doc.setFont(undefined, 'bold');

    if (isCheckingAccount) {
        const finalBalance = previousBalance + totalEntradas - totalSaidas;
        doc.text(`Saldo Final: ${formatCurrency(finalBalance)}`, 14, summaryY);
    } else {
        const totalFatura = totalSaidas - totalEntradas; // Total expenses minus payments/credits
        doc.text(`Total da Fatura: ${formatCurrency(totalFatura)}`, 14, summaryY);
    }

    const fileName = isCheckingAccount 
      ? `extrato_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`
      : `fatura_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`;

    doc.save(fileName);
};

export const generateCommentsPDF = (options: { 
    account: BankAccount, 
    period: { start: string, end: string }, 
    transactions: Transaction[] 
}) => {
    const { account, period, transactions } = options;
    const { jsPDF } = window.jspdf;

    // PDF em modo Paisagem (Landscape)
    const doc = new jsPDF({ orientation: 'landscape' });

    // Título do Relatório
    doc.setFontSize(18);
    doc.text('Relatório de Comentários e Observações', 14, 22);
    doc.setFontSize(11);
    doc.setTextColor(100);
    doc.text(`Conta: ${account.name}`, 14, 29);
    doc.text(`Período: ${formatDate(period.start)} a ${formatDate(period.end)}`, 14, 36);

    let currentY = 45;
    const margin = 14;
    const pageWidth = doc.internal.pageSize.getWidth();

    // Filtra apenas transações com comentários
    const transactionsWithComments = transactions
        .filter(t => t.comments && t.comments.trim() !== '')
        .sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    if (transactionsWithComments.length === 0) {
        doc.setFontSize(12);
        doc.setTextColor(0);
        doc.text('Nenhum comentário registrado para este período.', margin, currentY);
    } else {
        transactionsWithComments.forEach((t) => {
            // Cada comentário possui sua própria tabela separada
            doc.autoTable({
                startY: currentY,
                head: [[
                    { content: `TRANSAÇÃO: ${t.description || 'Sem Descrição'}`, styles: { halign: 'left' } },
                    { content: `DATA: ${formatDate(t.date)}`, styles: { halign: 'right' } }
                ]],
                body: [[
                    { content: t.comments, colSpan: 2, styles: { cellPadding: 5 } }
                ]],
                theme: 'grid',
                headStyles: { 
                    fillColor: [75, 85, 99], // Gray-600
                    textColor: [255, 255, 255],
                    fontSize: 10,
                    fontStyle: 'bold'
                },
                bodyStyles: {
                    fontSize: 10,
                    textColor: [31, 41, 55], // Gray-800
                },
                margin: { left: margin, right: margin },
                tableWidth: pageWidth - (margin * 2),
            });

            currentY = doc.lastAutoTable.finalY + 10;

            // Adiciona nova página se o espaço acabar
            if (currentY > doc.internal.pageSize.getHeight() - 20) {
                doc.addPage();
                currentY = 20;
            }
        });
    }

    // Numeração de páginas
    const pageCount = doc.internal.getNumberOfPages();
    for(let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        doc.setFontSize(9);
        doc.setTextColor(150);
        doc.text(
            `Página ${i} de ${pageCount}`, 
            pageWidth - margin - 20, 
            doc.internal.pageSize.getHeight() - 10
        );
    }

    doc.save(`relatorio_comentarios_${account.name.toLowerCase().replace(/\s/g, '_')}.pdf`);
};

import React, { useState } from 'react';
import { useAppData } from '../../hooks/useAppData';
import { generateCommentsPDF } from '../../utils/pdfGenerator';
import { MessageSquare, Download, AlertCircle, Banknote, Calendar } from 'lucide-react';
import { formatDate } from '../../utils/formatters';

const CommentsReport: React.FC = () => {
    const { accounts, transactions, getAccountById } = useAppData();

    const today = new Date();
    const firstDayOfMonth = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
    const todayISO = today.toISOString().split('T')[0];

    const [accountId, setAccountId] = useState('');
    const [startDate, setStartDate] = useState(firstDayOfMonth);
    const [endDate, setEndDate] = useState(todayISO);
    const [error, setError] = useState('');

    const handleGenerate = () => {
        if (!accountId) {
            setError('Por favor, selecione uma conta.');
            return;
        }
        if (!startDate || !endDate) {
            setError('Por favor, preencha as datas de início e fim.');
            return;
        }
        if (new Date(startDate) > new Date(endDate)) {
            setError('A data de início não pode ser posterior à data de fim.');
            return;
        }

        const account = getAccountById(accountId);
        if (!account) return;

        const start = new Date(startDate);
        const end = new Date(endDate);
        start.setUTCHours(0, 0, 0, 0);
        end.setUTCHours(23, 59, 59, 999);

        // Filtra transações da conta corrente que estão no período e possuem comentários
        const filteredTransactions = transactions.filter(t => {
            const tDate = new Date(t.date);
            return t.accountId === accountId && 
                   t.type === 'checking_account' && 
                   tDate >= start && 
                   tDate <= end && 
                   t.comments && t.comments.trim() !== '';
        });

        if (filteredTransactions.length === 0) {
            setError('Nenhum comentário encontrado para os filtros selecionados.');
            return;
        }

        setError('');
        generateCommentsPDF({
            account,
            period: { start: startDate, end: endDate },
            transactions: filteredTransactions
        });
    };

    return (
        <div className="space-y-8 animate-scale-in">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                    <h1 className="text-3xl font-bold text-gray-800">Relatório de Comentários</h1>
                    <p className="text-gray-500 mt-1">Gere um documento PDF exclusivo com as observações registradas na conta corrente.</p>
                </div>
            </div>

            <div className="bg-white p-6 rounded-2xl shadow-sm max-w-2xl">
                <div className="flex items-center gap-3 mb-6 text-blue-600">
                    <MessageSquare size={24} />
                    <h2 className="text-xl font-semibold">Configurar Relatório</h2>
                </div>

                <div className="space-y-6">
                    {error && (
                        <div className="bg-red-50 border-l-4 border-red-400 p-4 rounded flex items-center gap-3">
                            <AlertCircle className="text-red-500 flex-shrink-0" />
                            <p className="text-sm text-red-700 font-medium">{error}</p>
                        </div>
                    )}

                    <div>
                        <label htmlFor="rep-account" className="block text-sm font-medium text-gray-700 mb-1">Conta Bancária</label>
                        <div className="relative">
                            <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                                <Banknote className="h-5 w-5 text-gray-400" />
                            </div>
                            <select 
                                id="rep-account"
                                value={accountId}
                                onChange={(e) => setAccountId(e.target.value)}
                                className="block w-full rounded-lg border-gray-300 pl-10 focus:border-blue-500 focus:ring-blue-500 sm:text-sm p-3 border bg-white"
                            >
                                <option value="">Selecione uma conta...</option>
                                {accounts.map(acc => (
                                    <option key={acc.id} value={acc.id}>{acc.name}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div>
                            <label htmlFor="startDate" className="block text-sm font-medium text-gray-700 mb-1">Data de Início</label>
                            <div className="relative">
                                 <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                                    <Calendar className="h-5 w-5 text-gray-400" />
                                </div>
                                <input 
                                    type="date" 
                                    id="startDate" 
                                    value={startDate} 
                                    onChange={(e) => setStartDate(e.target.value)} 
                                    className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" 
                                />
                            </div>
                        </div>
                        <div>
                            <label htmlFor="endDate" className="block text-sm font-medium text-gray-700 mb-1">Data de Fim</label>
                             <div className="relative">
                                 <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                                    <Calendar className="h-5 w-5 text-gray-400" />
                                </div>
                                <input 
                                    type="date" 
                                    id="endDate" 
                                    value={endDate} 
                                    onChange={(e) => setEndDate(e.target.value)} 
                                    className="w-full pl-10 p-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500" 
                                />
                            </div>
                        </div>
                    </div>

                    <div className="pt-4">
                        <button 
                            onClick={handleGenerate} 
                            className="w-full flex items-center justify-center gap-2 px-6 py-4 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-all font-bold shadow-lg transform hover:-translate-y-0.5 active:translate-y-0"
                        >
                            <Download size={20} />
                            Gerar PDF de Comentários
                        </button>
                        <p className="text-center text-xs text-gray-400 mt-4">
                            O PDF será gerado em formato paisagem para melhor leitura dos auditores.
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

