}

export interface Transaction {
  id: string;
  description: string;
  nature: TransactionNature;
  accountId: string;
  categoryId: string;
  date: string; // ISO format
  value: number;
  type: 'checking_account' | 'credit_card';
  attachments?: Attachment[];
  comments?: string;
  numeroNota?: string;
  paymentMethod?: 'PIX' | 'Cartão de Débito' | 'BOLETO';
}

export interface Document {
    id: string;
    title: string;
    file_name: string;
    storage_path: string;
    created_at: string;
}

export interface KeepAliveLog {
  id: string;
  pinged_at: string;
}

